DECLARE
    V_JSON CLOB :=
        {{ JSON.stringify(
            JS_REPLACE_TERMINAL.getCreateRequestData()
        ) }};

    V_REQUEST_ID RAW(16) :=
        HEXTORAW(
            '{{ JS_REPLACE_TERMINAL.getRequestId() }}'
        );

BEGIN
    TALY_BO_REP.MMS_ONBOARDING_PKG.SAVE_REPLACE_TERMINAL_REQUEST(
        P_REQUEST_JSON => V_JSON,
        P_REQUEST_ID   => V_REQUEST_ID
    );
END;
